ph','data'=>['text'=>['fr'=>"Cookies : un cookie de session (authentification), un cookie de langue et une préférence de thème stockée localement. Aucun traceur publicitaire.",'en'=>'Cookies: a session cookie (authentication), a language cookie and a locally stored theme preference. No advertising trackers.']]]]]];foreach($p as $e=>$j){if(!Page::findBySlug($e,false)){Page::create(['slug'=>$e,'template'=>'page','title'=>$j['title'],'blocks'=>$j['blocks'],'is_published'=>1,'is_system'=>1]);}}$P('Pages système : legal, terms, privacy');$m=['main'=>['name'=>'Menu principal','items'=>[['key'=>'nav.features','url'=>'/features'],['key'=>'nav.pricing','url'=>'/pricing'],['key'=>'nav.download','url'=>'/download'],['key'=>'nav.docs','url'=>'/docs'],['key'=>'nav.blog','url'=>'/blog'],['key'=>'nav.contact','url'=>'/contact']]],'footer'=>['name'=>'Pied de page','items'=>[['key'=>'nav.legal','url'=>'/legal'],['key'=>'nav.terms','url'=>'/terms'],['key'=>'nav.privacy','url'=>'/privacy'],['key'=>'nav.status','url'=>'/status']]]];foreach($m as $e=>$W){if(!Menu::findBy('slug',$e)){Menu::create(['slug'=>$e,'name'=>$W['name'],'items'=>$W['items'],'updated_at'=>now()]);}}$P('Menus : main, footer');if(Post::count()===0){Post::create(['slug'=>'tout-video-1-0','title'=>['fr'=>'ToutPVR 1.0 est disponible','en'=>'ToutPVR 1.0 is out'],'excerpt'=>['fr'=>'Première version stable : NVR, IA de détection, panneau Aurora Glass et licences en ligne.','en'=>'First stable release: NVR, AI detection, Aurora Glass panel and online licensing.'],'blocks'=>[['type'=>'paragraph','data'=>['text'=>['fr'=>"Après des mois de développement, la version 1.0.0 du serveur ToutPVR est disponible : enregistrement continu ou sur événement, détection de personnes et de véhicules, zones et lignes virtuelles, notifications et mises à jour signées.",'en'=>'After months of development, ToutPVR server 1.0.0 is available: continuous or event recording, person and vehicle detection, virtual zones and lines, notifications and si